def seed_db(db):
    """Insere/atualiza instituicoes no banco."""
    city_count = db.query(Institution).filter(Institution.type == "city").count()
    other_count = db.query(Institution).filter(Institution.type != "city").count()

    if city_count >= 5000 and other_count > 0:
        return  # ja esta completo

    # Seed de escolas/empresas/universidades se necessario
    if other_count == 0:
        print("[SEED] Inserindo escolas, empresas e universidades...")
        non_city = (
            [(n, "school",     s, c) for n, s, c in ESCOLAS] +
            [(n, "company",    s, c) for n, s, c in EMPRESAS] +
            [(n, "university", s, c) for n, s, c in UNIVERSIDADES]
        )
        db.add_all([Institution(name=n, type=t, state=s, city=c, approved=True)
                    for n, t, s, c in non_city])
        db.commit()
        print(f"[SEED] {len(non_city)} instituicoes inseridas.")

    # Seed/atualizacao de municipios se incompleto
    if city_count < 5000:
        print(f"[SEED] Atualizando municipios ({city_count} -> {len(CIDADES)})...")
        db.query(Institution).filter(Institution.type == "city").delete()
        db.add_all([Institution(name=n, type="city", state=s, city=c, approved=True)
                    for n, s, c in CIDADES])
        db.commit()
        print(f"[SEED] {len(CIDADES)} municipios inseridos.")
